sys_script_include.script:
var starWarsGMUtil = Class.create();
starWarsGMUtil.prototype = {
    initialize: function() {},

    getCampaignOrgs: function(campaign) {
        var orgs = new GlideRecord('x_176383_star_wars_organization');
        orgs.addQuery('campaign', campaign);
        orgs.orderBy('name');
        orgs.query();
        var orgsArray = [];
        while (orgs.next()) {
            var orgRec = {
                name: orgs.getDisplayValue(),
                sys_id: orgs.getUniqueValue(),
                active: orgs.active,
                description: orgs.description + '',
            };
            orgsArray.push(orgRec);
        }
        return orgsArray;
    },

    getCampaignLocations: function(campaign) {
        var locations = new GlideRecord('x_176383_star_wars_location');
        locations.addQuery('campaign', campaign);
        locations.orderBy('planet');
        locations.orderBy('name');
        var locationsArray = [];
        locations.query();
        while (locations.next()) {
            var locRec = {
                name: locations.getDisplayValue(),
                sys_id: locations.getUniqueValue(),
                planetID: locations.planet.sys_id + '',
                planet: locations.planet.getDisplayValue(),
                description: locations.description + ''
            };
            locationsArray.push(locRec);
        }
        return locationsArray;
    },

    getCampaignArtifacts: function(campaign) {
        var artifacts = new GlideRecord('x_176383_star_wars_special_item_artifact');
        artifacts.addQuery('campaign', campaign);
        artifacts.orderBy('location');
        artifacts.orderBy('name');
        artifacts.query();
        var artifactsArray = [];
        while (artifacts.next()) {
            var artRec = {
                name: artifacts.getDisplayValue(),
                sys_id: artifacts.getUniqueValue(),
                locationID: artifacts.location.sys_id + '',
                location: artifacts.location.getDisplayValue(),
                description: artifacts.description + ''
            };
            artifactsArray.push(artRec);
        }
        return artifactsArray;
    },

    getCampaignSessionNotes: function(campaign) {
        var notes = new GlideRecord('x_176383_star_wars_session_note');
        notes.addQuery('campaign', campaign);
        notes.orderByDesc('sys_created_on');
        notes.query();
        var sessionNotesArray = [];
        while (notes.next()) {
            var notesObj = {
                sysID: notes.sys_id + '',
                character: notes.character.getDisplayValue(),
                description: notes.notes + '',
                name: notes.title + '',
                date: notes.session_date + ''
            };
            sessionNotesArray.push(notesObj);
        }
        return sessionNotesArray;
    },

    getCampaignSessionPlans: function(campaign) {
        var sessionPlans = new GlideRecord('x_176383_star_wars_session_plan');
        sessionPlans.addQuery('campaign', campaign).addCondition('state', '!=', 'cancelled');
        sessionPlans.orderBy('order');
        sessionPlans.query();
        var openSessionPlansArray = [];
        var completedSessionPlansArray = [];
        while (sessionPlans.next()) {
            var spRec = {
                name: sessionPlans.getDisplayValue(),
                sys_id: sessionPlans.getUniqueValue(),
                order: sessionPlans.order + '',
                state: sessionPlans.state + '',
                outline: sessionPlans.outline + '',
                description: sessionPlans.outline + '',
                gm_notes: sessionPlans.gm_notes + '',
            };
            if (spRec.state == 'completed') {
                completedSessionPlansArray.push(spRec);
            } else {
                openSessionPlansArray.push(spRec);
            }
        }
        var returnObj = {
            openSessions: openSessionPlansArray,
            completedSessions: completedSessionPlansArray
        };
        return returnObj;
    },

    getMyCampaigns: function() {
        var campaignGR = new GlideRecord('x_176383_star_wars_campaign');
        campaignGR.addQuery('game_master', gs.getUserID());
        campaignGR.orderBy('name');
        campaignGR.query();
        var campaigns = [];
        while (campaignGR.next()) {
            var rec = {
                name: campaignGR.getDisplayValue(),
                description: campaignGR.description + '',
                sys_id: campaignGR.getUniqueValue()
            };
            rec.locationCount = this._getLocationCount(rec.sys_id);
            rec.organizationCount = this._getOrgCount(rec.sys_id);
            rec.artifactCount = this._getArtifactCount(rec.sys_id);
            rec.charactersCount = this._getCharactersCount(rec.sys_id);
            rec.sessionNotesCount = this._getSessionNotesCount(rec.sys_id);
            rec.sessionPlanCount = this._getSessionPlanCount(rec.sys_id);
            campaigns.push(rec);
        }
        return campaigns;
    },

    /*retrieve specific record for full page campaign detail page*/
    getFullPageCampaignDetail: function(table, sysID) {
        var rec = new GlideRecord(table);
        rec.get(sysID);
        var returnObj = {
            name: rec.getDisplayValue(),
            description: rec.description + ''
        };

        if (rec.planet) {
            returnObj.planet = rec.planet.getDisplayValue();
        }

        if (rec.location) {
            returnObj.location = rec.location.getDisplayValue();
        }

        if (table == 'x_176383_star_wars_session_plan') {
            returnObj.outline = rec.outline + '';
            returnObj.description = rec.outline + '';
            returnObj.gm_notes = rec.gm_notes + '';
        }
        return returnObj;
    },

    //campaign session functions
    getActiveSessionDetails: function(campaign) {
        var sessionGR = new GlideRecord('x_176383_star_wars_game_session');
        sessionGR.addQuery('campaign', campaign).addCondition('active', true);
        sessionGR.query();
        var sessionObj = {
            hasActiveSession: false,
            activeSessionID: ''
        };

        if (sessionGR.next()) {
            sessionObj.hasActiveSession = true;
            sessionObj.activeSessionID = sessionGR.sys_id + '';
            sessionObj.activeSessionURL = '?id=star_wars_game_session&table=x_176383_star_wars_game_session&sys_id=' + sessionGR.sys_id.toString() + '&campaign=' + campaign;
        }
        return sessionObj;
    },

    startNewSession: function(campaign, activeSessionDetails) {
        var sessionGR = new GlideRecord('x_176383_star_wars_game_session');
        if (activeSessionDetails.hasActiveSession) {
            sessionGR.get(activeSessionDetails.activeSessionID);
            sessionGR.active = false;
            sessionGR.update();
        }

        sessionGR.initialize();
        sessionGR.campaign = campaign;
        sessionGR.insert();
        return '?id=star_wars_game_session&table=x_176383_star_wars_game_session&sys_id=' + sessionGR.sys_id.toString() + '&campaign=' + campaign;
    },

    getCampaignEncounters: function(campaign) {
        var encounters = new GlideRecord('x_176383_star_wars_encounter');
        encounters.addQuery('campaign', campaign);
        encounters.orderBy('order');
        encounters.query();
        var returnArray = [];
        while (encounters.next()) {
            var encounterObj = {
                name: encounters.name + '',
                sys_id: encounters.getUniqueValue(),
                description: encounters.description + '',
                order: parseInt(encounters.order),
                state: {
                    display: encounters.state.getDisplayValue(),
                    value: encounters.getValue('state')
                }
            };
            returnArray.push(encounterObj);
        }
        return returnArray;
    },

    fetchAdversaries: function() {
        var adversaryGR = new GlideRecord('x_176383_star_wars_adversary');
        adversaryGR.addQuery('sys_class_name', 'x_176383_star_wars_adversary');
        adversaryGR.query();
        var adversariesArray = [];
        while (adversaryGR.next()) {
            var adversaryObj = {
                name: adversaryGR.getDisplayValue(),
                sys_id: adversaryGR.getUniqueValue(),
                type: adversaryGR.type.getDisplayValue(),
				description: adversaryGR.description + '',
                skills: this._getEncounterAdversarySkills(adversaryGR.sys_id.toString(), '', false),
                characteristics: {
                    brawn: parseInt(adversaryGR.brawn),
                    agility: parseInt(adversaryGR.agility),
                    intellect: parseInt(adversaryGR.intellect),
                    cunning: parseInt(adversaryGR.cunning),
                    willpower: parseInt(adversaryGR.willpower),
                    presence: parseInt(adversaryGR.presence)
                },
                combat: {
                    woundThreshold: parseInt(adversaryGR.wound_threshold),
                    strainThreshold: parseInt(adversaryGR.strain_threshold),
                    defenseMelee: parseInt(adversaryGR.melee_defense),
                    defenseRanged: parseInt(adversaryGR.ranged_defense),
                    soak: parseInt(adversaryGR.soak),
                    weapons: this._getEncounterAdversaryWeapons(adversaryGR.sys_id.toString())
                }
            };
			adversariesArray.push(adversaryObj);
        }
		return adversariesArray;
    },

    getEncounterAdversaries: function(encounterID) {
        var adversariesArray = [];
        var adversariesGR = new GlideRecord('x_176383_star_wars_encounter_adversary');
        adversariesGR.addQuery('encounter', encounterID);
        adversariesGR.orderBy('name');
        adversariesGR.query();
        while (adversariesGR.next()) {
            var adversaryObj = {
                name: adversariesGR.name + '',
                sys_id: adversariesGR.sys_id.toString(),
                description: adversariesGR.description + '',
                skills: this._getEncounterAdversarySkills(adversariesGR.adversary.sys_id.toString(), adversariesGR, true),
                characteristics: {
                    agility: parseInt(adversariesGR.agility),
                    brawn: parseInt(adversariesGR.brawn),
                    cunning: parseInt(adversariesGR.cunning),
                    intellect: parseInt(adversariesGR.intellect),
                    presence: parseInt(adversariesGR.presence),
                    willpower: parseInt(adversariesGR.willpower)
                },
                combat: {
                    woundThreshold: parseInt(adversariesGR.wound_threshold),
                    woundCurrent: parseInt(adversariesGR.current_wound),
					woundPerMinion: parseInt(adversariesGR.wounds_per_minion),
					minionsInGroup: parseInt(adversariesGR.number_of_minions_in_group),
                    strainThreshold: parseInt(adversariesGR.strain_threshold),
                    strainCurrent: parseInt(adversariesGR.current_strain),
                    defenseMelee: parseInt(adversariesGR.melee_defense),
                    defenseRanged: parseInt(adversariesGR.ranged_defense),
                    soak: parseInt(adversariesGR.soak),
                    weapons: this._getEncounterAdversaryWeapons(adversariesGR.adversary.sys_id.toString())
                },
                type: {
                    display: adversariesGR.type.getDisplayValue(),
                    value: adversariesGR.getValue('type')
                }
            };
            adversariesArray.push(adversaryObj);
        }
        return adversariesArray;
    },

    _getEncounterAdversarySkills: function(adversaryID, encounterAdversary, calculateMinionSkillRanks) {
        var adversarySkillsArray = [];
        var asGR = new GlideRecord('x_176383_star_wars_adversary_skill');
        asGR.addQuery('adversary', adversaryID);
        asGR.orderBy('skill.name');
        asGR.query();
        while (asGR.next()) {
            var asObj = {
                name: asGR.skill.getDisplayValue(),
                characteristic: asGR.skill.characteristic.getDisplayValue(),
                type: asGR.skill.type.getDisplayValue(),
                description: asGR.skill.description + '',
                ranks: parseInt(asGR.ranks),
                minionSkill: asGR.is_minion_skill ? true : false,
                sysID: asGR.skill.sys_id.toString()
            };
			if(encounterAdversary.type == 'minion' && asObj.minionSkill && calculateMinionSkillRanks){
				asObj.ranks = encounterAdversary.number_of_minions_in_group - 1;
			}
            adversarySkillsArray.push(asObj);
        }
        return adversarySkillsArray;
    },

    _getEncounterAdversaryWeapons: function(encounterAdversaryID) {
        var weaponsArray = [];
        var eawGR = new GlideRecord('x_176383_star_wars_adversary_weapon');
        eawGR.addQuery('adversary', encounterAdversaryID);
        eawGR.orderBy('weapon.name');
        eawGR.query();
        while (eawGR.next()) {
            var eawObj = {
                name: eawGR.weapon.getDisplayValue(),
                sys_id: eawGR.sys_id.toString(),
                skill: {
                    display: eawGR.weapon.skill_used.getDisplayValue(),
                    sysID: eawGR.weapon.skill_used.sys_id + ''
                },
                range: eawGR.weapon.range.getDisplayValue(),
                damage: parseInt(eawGR.weapon.base_damage),
                crit: parseInt(eawGR.weapon.critical_rating),
                qualities: this._getEncounterAdvesaryWeaponQualities(eawGR.weapon.sys_id.toString())
            };
            weaponsArray.push(eawObj);
        }
        return weaponsArray;
    },

    _getEncounterAdvesaryWeaponQualities: function(gearID) {
        var qualitiesArray = [];
        var eawqGR = new GlideRecord('x_176383_star_wars_gear_special');
        eawqGR.addQuery('item', gearID);
        eawqGR.query();
        while (eawqGR.next()) {
            var qualityObj = {
                name: eawqGR.weapon_quality.getDisplayValue(),
                rank: parseInt(eawqGR.rank),
                description: eawqGR.weapon_quality.description + ''
            };
            qualitiesArray.push(qualityObj);
        }
        return qualitiesArray;
    },

    _getLocationCount: function(campaign) {
        var locationGR = new GlideRecord('x_176383_star_wars_location');
        locationGR.addQuery('campaign', campaign);
        locationGR.query();
        return locationGR.getRowCount();
    },

    _getOrgCount: function(campaign) {
        var orgCount = new GlideRecord('x_176383_star_wars_organization');
        orgCount.addQuery('campaign', campaign);
        orgCount.query();
        return orgCount.getRowCount();
    },

    _getArtifactCount: function(campaign) {
        var artCount = new GlideRecord('x_176383_star_wars_special_item_artifact');
        artCount.addQuery('campaign', campaign);
        artCount.query();
        return artCount.getRowCount();
    },

    _getCharactersCount: function(campaign) {
        var cCount = new GlideRecord('x_176383_star_wars_character');
        cCount.addQuery('campaign', campaign);
        cCount.query();
        return cCount.getRowCount();
    },

    _getSessionNotesCount: function(campaign) {
        var notes = new GlideRecord('x_176383_star_wars_session_note');
        notes.addQuery('campaign', campaign);
        notes.query();
        return notes.getRowCount();
    },

    _getSessionPlanCount: function(campaign) {
        var spCount = new GlideRecord('x_176383_star_wars_session_plan');
        spCount.addQuery('campaign', campaign);
        spCount.query();
        return spCount.getRowCount();
    },

    type: 'starWarsGMUtil'
};
